function createClient(provider, apiKey) {
    switch (provider) {
        case 'openai':
            return { type: 'openai', client: new OpenAI({ apiKey }) };

        case 'openrouter':
            return {
                type: 'openrouter',
                client: new OpenAI({
                    apiKey,
                    baseURL: 'https://openrouter.ai/api/v1',
                    defaultHeaders: {
                        'HTTP-Referer': 'https://github.com/antnsn/Lexorium',
                        'X-Title': 'Lexorium',
                    },
                }),
            };

        case 'anthropic': {
            let Anthropic;
            try {
                Anthropic = require('@anthropic-ai/sdk');
            } catch (e) {
                throw new Error(
                    'Anthropic SDK not installed. Run: npm install @anthropic-ai/sdk'
                );
            }
            // Handle both ESM default export and direct constructor
            const AnthropicClass = Anthropic.default || Anthropic;
            return { type: 'anthropic', client: new AnthropicClass({ apiKey }) };
        }

        default:
            throw new Error(`Unknown provider: ${provider}`);
    }
}

This function creates and returns an API client object based on the selected `provider`.

### What it does
- Accepts:
  - `provider`: which AI provider to use
  - `apiKey`: the API key for that provider
- Returns an object with:
  - `type`: the provider name
  - `client`: an initialized SDK client

### Provider handling
- **`openai`**
  - Creates a standard `OpenAI` client using the given API key.

- **`openrouter`**
  - Also uses the `OpenAI` client, but configures it with:
    - a custom `baseURL`: `https://openrouter.ai/api/v1`
    - custom headers:
      - `HTTP-Referer`
      - `X-Title`
  - This is needed because OpenRouter is OpenAI-compatible but requires its own endpoint and often app-identifying headers.

- **`anthropic`**
  - Dynamically loads the `@anthropic-ai/sdk` package using `require()`.
  - If the package is not installed, it throws a helpful error telling the user how to install it.
  - Handles both:
    - default ESM export
    - direct CommonJS constructor
  - Then returns an initialized Anthropic client.

- **default**
  - Throws an error if the provider is unknown.

### Why dynamic import is useful here
The Anthropic SDK is only required when the `anthropic` provider is selected. This avoids forcing users to install that package unless they actually need it.

### Potential improvement
One thing to note is that `OpenAI` must already be imported or defined elsewhere, otherwise the `openai` and `openrouter` cases will fail.

